"""Original GI infections and tropical gastroenterology questions."""
from qbank_authoring import question,ref,finalize
ID=ref('IDSA Infectious Diarrhea Clinical Practice Guideline','https://www.idsociety.org/practice-guideline/infectious-diarrhea')
CD=ref('SHEA/IDSA 2021 Focused Adult C. difficile Guideline','https://www.idsociety.org/practice-guideline/clostridioides-difficile-2021-focused-update/')
TR=ref('CDC Yellow Book: Post-Travel Diarrhea','https://www.cdc.gov/yellow-book/hcp/post-travel-evaluation/post-travel-diarrhea.html')
TD=ref('CDC Yellow Book: Travelers’ Diarrhea','https://www.cdc.gov/yellow-book/hcp/preparing-international-travelers/travelers-diarrhea.html')
ST=ref('CDC Clinical Care of Strongyloides','https://www.cdc.gov/strongyloides/hcp/clinical-care/index.html')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))

q('Why can oral rehydration solution remain effective in severe secretory diarrhea?', 'Intestinal sodium–glucose cotransport remains available to promote water absorption',[
 ('It stops all toxin production immediately','Rehydration treats fluid loss rather than directly neutralizing all toxins.'),('It works only by providing free water without electrolytes','Appropriate sodium and glucose composition is central to effective absorption.'),('It requires restoration of every chloride-secretory pathway before any fluid can be absorbed','Absorption can continue despite ongoing secretion.')],
 'Exploit a preserved absorptive mechanism', '**Coupled sodium and glucose uptake supports water absorption even during ongoing secretory loss.**', ['Use an appropriate ORS formulation rather than very sugary soft drinks.','Measure and replace ongoing losses as well as the initial deficit.'], '**Match the route to perfusion and tolerance.**', ['Shock or inability to drink can require intravenous resuscitation first.','Resume suitable enteral intake as the patient stabilizes.'], [['ORS','Coupled absorption plus electrolyte replacement'],['Very sugary low-sodium drinks','May worsen osmotic burden'],['Shock','Immediate IV resuscitation pathway']], [ID])
q('An adult has acute diarrhea with high fever, bloody stools and marked abdominal tenderness. What testing approach is appropriate?', 'Targeted stool testing for invasive bacterial pathogens and Shiga toxin-producing E. coli, guided by exposure and severity',[
 ('No stool testing because all acute diarrhea is viral','The inflammatory and severe features warrant etiological assessment.'),('Only a fecal occult blood test','Visible blood is already established and occult testing does not identify the cause.'),('A routine tumor-marker panel as the first infectious evaluation','This does not assess the likely acute pathogens.')],
 'Inflammatory features change the diagnostic threshold', '**Blood, fever, severe pain or sepsis justify a broader pathogen assessment.**', ['Ask about food, travel, immune status, drugs and sick contacts.','Culture or susceptibility testing can still be needed after a molecular result.'], '**Use results to refine treatment and public-health action.**', ['Not every detected organism has the same antibiotic indication.','Suspected enteric fever or systemic illness may also require blood cultures.'], [['Mild brief watery illness','Often limited testing'],['Bloody/febrile/severe illness','Targeted pathogen testing'],['Systemic infection','Consider blood cultures']], [ID], 'clinical_scenario')
q('Bloody diarrhea follows undercooked beef exposure. Shiga toxin-producing E. coli is detected. What is the key treatment principle?', 'Provide supportive care and avoid antibiotics and antimotility drugs because of potential harm including HUS risk',[
 ('Start a fluoroquinolone routinely to prevent HUS','Antibiotics are avoided in STEC because they can increase harm.'),('Use loperamide to suppress all stool passage','Antimotility therapy is avoided in this setting.'),('Exclude kidney injury risk once the diarrhea begins to improve','HUS can emerge after the initial gastrointestinal phase.')],
 'A bacterial diagnosis does not always imply an antibiotic benefit', '**STEC management prioritizes hydration and surveillance for complications.**', ['Monitor blood count, platelets and renal function when clinically indicated.','Thrombotic microangiopathy can evolve after the diarrheal onset.'], '**Separate STEC from other dysentery pathogens before indiscriminate treatment.**', ['The organism and toxin phenotype influence antibiotic decisions.','Escalate promptly for oliguria, pallor, thrombocytopenia or neurological change.'], [['STEC','Supportive care, avoid harmful routine drugs'],['HUS','Hemolysis, thrombocytopenia, kidney injury'],['Improving stool','Does not eliminate later risk']], [ID,ref('CDC Treatment of E. coli Infection','https://www.cdc.gov/ecoli/treatment/index.html')], 'clinical_scenario')
q('Which adult with nontyphoidal Salmonella gastroenteritis is most likely to require antibiotic treatment?', 'An immunocompromised patient with systemic illness and suspected bacteremia',[
 ('Every healthy adult with a short self-limited watery episode','Antibiotics are not routinely indicated for uncomplicated low-risk disease.'),('A fully recovered low-risk adult solely to shorten asymptomatic carriage','Antibiotics can prolong carriage and are not used routinely for that purpose.'),('A patient selected only because stool color is green','Stool color does not establish an antibiotic indication.')],
 'Host and invasive-disease risk determine treatment', '**Uncomplicated nontyphoidal Salmonella is often managed supportively, but high-risk or invasive illness differs.**', ['Immunosuppression, vascular disease and severe disease may alter the risk-benefit balance.','Obtain appropriate cultures and use susceptibility-informed treatment.'], '**Do not confuse nontyphoidal gastroenteritis with enteric fever.**', ['Typhoid has a different systemic disease framework.','Persistent bacteremia requires evaluation for focal infection.'], [['Low-risk self-limited illness','Often supportive care'],['High-risk/invasive disease','Antibiotics indicated or strongly considered'],['Enteric fever','Separate treatment pathway']], [ID,TR])
q('A traveler has severe febrile dysentery. Which empiric antibiotic principle is most appropriate?', 'Choose an agent using travel-associated resistance patterns and severity; azithromycin is often favored for febrile dysentery, with susceptibility testing guiding refinement',[
 ('Assume ciprofloxacin is reliably active in every region','Fluoroquinolone resistance is important in several travel-associated pathogens.'),('Use metronidazole as universal monotherapy for all bacterial dysentery','It does not cover the usual invasive bacterial causes adequately.'),('Ignore resistance because all Shigella and Campylobacter remain uniformly susceptible','Resistance and extensively resistant strains can change treatment.')],
 'Geography and organism susceptibility matter', '**An empiric choice is provisional and should be revised when microbiology clarifies the cause.**', ['Sepsis, immunocompromise or suspected extensively resistant infection can require specialist-directed broader treatment.','Avoid indiscriminate empiric antibiotics in a phenotype concerning for STEC.'], '**Pair treatment with hydration and diagnostic assessment.**', ['A culture can provide susceptibility information that a multiplex panel may not.','Clinical failure should prompt reassessment rather than repeated blind courses.'], [['Febrile dysentery','Resistance-informed empiric decision'],['Severe/XDR concern','Specialist-directed escalation'],['STEC phenotype','Antibiotic caution']], [ID,TD], 'clinical_scenario')
q('A patient has three new unformed stools in 24 hours after antibiotics, without recent laxative use. What is the appropriate C. difficile testing principle?', 'Test an appropriate unformed stool sample in the compatible clinical syndrome',[
 ('Screen every asymptomatic inpatient with NAAT and treat every positive result','Colonization is not the same as symptomatic infection.'),('Use a formed stool specimen from an asymptomatic patient as routine diagnostic confirmation','That is generally an inappropriate testing context.'),('Require pseudomembranes on colonoscopy before any stool test','Most cases are diagnosed without endoscopy.')],
 'Diagnostic stewardship protects the distinction between carriage and infection', '**A compatible diarrheal syndrome should precede testing.**', ['NAAT can detect a toxigenic organism even when it is not causing the symptoms.','Local multistep algorithms and preagreed stool-submission criteria improve interpretation.'], '**Review alternative causes of diarrhea.**', ['Laxatives, tube feeds and other infections can confound the picture.','Ileus in fulminant disease is an important exception to the usual stool-frequency presentation.'], [['Compatible unformed stool','Appropriate testing context'],['Asymptomatic NAAT positivity','Possible colonization'],['Fulminant ileus','Can occur without frequent stool']], [CD,ref('SHEA/IDSA C. difficile Diagnostic and Management Guideline','https://www.idsociety.org/practice-guideline/clostridium-difficile/')], 'clinical_scenario')
q('For an initial nonfulminant adult C. difficile episode, what does the SHEA/IDSA 2021 focused update prefer when resources permit?', 'Fidaxomicin, with oral vancomycin remaining an acceptable alternative',[
 ('Intravenous vancomycin alone','IV vancomycin does not provide the required luminal therapy for routine CDI.'),('Loperamide alone','This does not eradicate the infection and is not definitive treatment.'),('A carbapenem as the standard targeted monotherapy','Broad systemic antibacterial treatment is not the standard targeted regimen.')],
 'Choose therapy that reaches the colonic infection', '**Fidaxomicin improves sustained response largely through lower recurrence, while oral vancomycin remains acceptable.**', ['The recommendation is resource-sensitive.','This nonfulminant recommendation must not be extrapolated uncritically to fulminant disease.'], '**Remove modifiable contributors when feasible.**', ['Review unnecessary concurrent antibiotics.','Use infection-control precautions and monitor severity.'], [['Nonfulminant CDI','Fidaxomicin preferred when feasible'],['Alternative','Oral vancomycin'],['Fulminant disease','Different treatment framework']], [CD])
q('C. difficile colitis is complicated by shock and ileus. What is the standard antimicrobial direction?', 'High-dose enteral vancomycin plus IV metronidazole, with rectal vancomycin considered for ileus and urgent surgical assessment',[
 ('Fidaxomicin alone based solely on the nonfulminant recommendation','Evidence for fulminant disease does not support simply substituting that pathway.'),('IV vancomycin alone','It does not adequately target luminal colonic CDI.'),('Delay treatment until diarrhea resumes','Ileus can be a manifestation of fulminant disease and requires urgent action.')],
 'Fulminant physiology changes drug delivery and escalation', '**Ileus can impede distribution of an orally delivered luminal agent.**', ['Rectal delivery may be added under the relevant protocol.','IV metronidazole is combined with luminal vancomycin rather than used to justify delaying source-control assessment.'], '**Escalate early when shock, megacolon or perforation risk is present.**', ['Resuscitation and close monitoring are essential.','Surgery is not reserved for an already completed perforation.'], [['Shock/ileus','Fulminant CDI'],['Antimicrobials','Enteral vancomycin plus IV metronidazole'],['Ileus','Consider rectal delivery and surgery review']], [CD,ref('SHEA/IDSA C. difficile Management Guideline','https://www.idsociety.org/practice-guideline/clostridium-difficile/')], 'clinical_scenario')
q('After successful treatment of C. difficile infection, diarrhea resolves. What is the role of a routine test of cure?', 'Do not perform routine testing in an asymptomatic recovered patient',[
 ('Repeat NAAT daily until negative','NAAT can remain positive after clinical recovery.'),('Continue antibiotics indefinitely while any assay remains positive','Persistent detection alone is not a treatment indication.'),('Use a positive result alone to diagnose a symptomatic recurrence that has not occurred','Recurrence requires a compatible clinical assessment.')],
 'Clinical recovery and persistent organism detection can diverge', '**A test of cure can misclassify carriage as continuing disease.**', ['New diarrhea should be evaluated if it occurs.','Postinfectious bowel symptoms and other causes may mimic recurrence.'], '**Treat the patient’s syndrome rather than an isolated residual result.**', ['Reassess medication and exposure history for new symptoms.','Use appropriate retesting criteria instead of scheduled surveillance assays.'], [['Asymptomatic recovery','No routine test of cure'],['Persistent NAAT positivity','May reflect carriage'],['New diarrhea','Reevaluate clinically']], [ref('SHEA/IDSA C. difficile Diagnostic Guideline','https://www.idsociety.org/practice-guideline/clostridium-difficile/')])
q('In an adult with a first recurrence of nonfulminant CDI after standard oral vancomycin, which is an appropriate treatment option?', 'Fidaxomicin; a vancomycin taper/pulse is also an accepted alternative in the appropriate setting',[
 ('Repeated metronidazole as the mandatory preferred regimen','It is not the preferred recurrent-disease strategy.'),('A test-of-cure result alone without recurrent symptoms','That would not establish the stated recurrence syndrome.'),('No therapy because recurrence cannot occur after vancomycin','Recurrence is a recognized clinical problem.')],
 'A recurrent episode requires a recurrence-aware regimen', '**The prior regimen and patient risk influence the next choice.**', ['The focused guideline favors fidaxomicin over a standard vancomycin course for recurrence when feasible.','Multiple recurrences can require additional microbiota-based strategies under current protocols.'], '**Confirm that recurrent symptoms truly fit CDI.**', ['Postinfectious IBS is a possible mimic.','Avoid unsupported prolonged antimicrobial exposure for an isolated positive test.'], [['First recurrence','Fidaxomicin consideration'],['Alternative','Vancomycin taper/pulse'],['Multiple recurrences','Broader specialist prevention strategy']], [CD])
q('Persistent diarrhea, bloating and greasy stools follow a mountain-water exposure. Which diagnostic direction is most appropriate?', 'Test for Giardia using an appropriate stool antigen or molecular assay',[
 ('Assume an invasive bacterial dysentery despite absent blood or fever','The prolonged malabsorptive phenotype suggests a protozoal alternative.'),('Use a pancreatic tumor marker as the first organism test','This does not identify Giardia.'),('Diagnose celiac disease solely from the exposure history','Celiac disease is not acquired from contaminated drinking water.')],
 'Duration and stool phenotype narrow the pathogen differential', '**Giardia commonly causes prolonged diarrhea and malabsorptive symptoms.**', ['A targeted antigen or PCR test can be useful.','Several samples or a broader evaluation may be needed when suspicion persists despite a negative study.'], '**Treat the identified infection and reassess persistent symptoms.**', ['Postinfectious lactose intolerance or IBS may remain after eradication.','Reinfection and incomplete treatment are different explanations for continued positivity.'], [['Water exposure plus greasy diarrhea','Giardia concern'],['Antigen/PCR','Targeted stool diagnosis'],['After eradication','Consider secondary intolerance']], [TR], 'clinical_scenario')
q('Which treatment sequence is appropriate for invasive intestinal Entamoeba histolytica infection?', 'Metronidazole or tinidazole followed by a luminal amoebicide such as paromomycin',[
 ('Metronidazole alone as guaranteed eradication of luminal cyst carriage','A luminal agent is needed after tissue-active therapy.'),('Paromomycin alone for severe invasive colitis','A luminal agent alone does not adequately treat tissue invasion.'),('A fluoroquinolone alone as standard amoebic treatment','This does not provide the required antiamoebic sequence.')],
 'Tissue invasion and luminal carriage are separate targets', '**A nitroimidazole treats invasive disease but should be followed by luminal eradication.**', ['Confirm the pathogen when possible because nonpathogenic Entamoeba species can look similar microscopically.','Steroid exposure can be dangerous in unrecognized amoebic colitis.'], '**Do not stop at symptomatic improvement.**', ['A second drug phase prevents persisting luminal infection.','Choice depends on local availability, contraindications and the disease site.'], [['Tissue-active phase','Metronidazole/tinidazole'],['Luminal phase','Paromomycin or another appropriate agent'],['Microscopy alone','May not distinguish look-alike species']], [TR,TD])
q('Stool microscopy reports Entamoeba histolytica/dispar cysts in a patient with chronic gastrointestinal symptoms. What is the main diagnostic limitation?', 'Routine morphology may not distinguish pathogenic E. histolytica from nonpathogenic look-alike species',[
 ('Every morphologically similar cyst proves invasive amoebiasis','Species and evidence of invasion require better assessment.'),('A cyst report proves an amoebic liver abscess','An intestinal microscopy result does not establish hepatic disease.'),('Molecular or species-specific antigen tests have no role','They can clarify a clinically important distinction.')],
 'A microscopy label can contain biological uncertainty', '**Species-specific antigen or PCR can improve diagnostic specificity.**', ['Interpret symptoms and other findings rather than treating the report as complete proof.','An alternative colitis diagnosis can coexist or be mistaken for amoebiasis.'], '**Choose treatment for the confirmed clinical form.**', ['Invasive disease requires tissue-active then luminal treatment.','Asymptomatic confirmed luminal E. histolytica has a different treatment scope.'], [['Routine microscopy','Potential species ambiguity'],['Species-specific assay','Clarifies pathogenic infection'],['Invasive syndrome','Requires tissue-active treatment']], [TR])
q('Relapsing watery diarrhea follows fresh-produce exposure. Stool testing identifies Cyclospora cayetanensis. Which drug is preferred?', 'Trimethoprim–sulfamethoxazole',[
 ('Metronidazole','This is not the standard effective treatment for Cyclospora.'),('Oral vancomycin','This targets CDI rather than this protozoal infection.'),('Praziquantel','This is used for selected helminths, not Cyclospora.')],
 'Not all protozoal diarrhea responds to the same drug', '**Cyclospora can cause prolonged or relapsing watery diarrhea.**', ['The laboratory may need a specific request or molecular panel that includes it.','Routine ova-and-parasite examination may not identify every coccidian pathogen.'], '**Treat the organism and replace fluid losses.**', ['Immune status can affect disease severity and treatment duration.','Drug allergy or treatment failure requires specialist alternatives rather than assuming metronidazole equivalence.'], [['Cyclospora','TMP–SMX'],['Giardia','Different antiprotozoal options'],['C. difficile','Different antibacterial pathway']], [TR,TD], 'clinical_scenario')
q('An adult with advanced HIV has chronic watery diarrhea due to Cryptosporidium. What is a central treatment principle?', 'Optimize antiretroviral therapy to restore immunity, together with hydration and nutritional support',[
 ('Nitazoxanide guarantees cure regardless of immune status','Effectiveness is less certain in significant immunosuppression.'),('Use corticosteroids to eradicate the parasite','Steroids do not provide pathogen eradication and may worsen susceptibility.'),('Withhold ART until all stool tests become negative','Immune restoration is a central part of management.')],
 'Host immunity can be the decisive therapeutic factor', '**Persistent cryptosporidiosis can be severe with advanced cellular immunodeficiency.**', ['Assess dehydration, electrolytes and nutritional losses.','Antiparasitic choices must be interpreted in the immune context.'], '**Treat the underlying immune deficit as well as symptoms.**', ['ART optimization should be coordinated with HIV care.','A co-pathogen or biliary complication may need separate assessment.'], [['Advanced HIV','Immune restoration central'],['Supportive care','Fluid and nutritional replacement'],['Nitazoxanide','Not a guaranteed cure in immunosuppression']], [ref('CDC Clinical Care of Cryptosporidiosis','https://www.cdc.gov/cryptosporidium/hcp/clinical-care/index.html')], 'clinical_scenario')
q('A patient from a Strongyloides-endemic region is about to receive high-dose corticosteroids. Why is a remote exposure history relevant?', 'Autoinfection can maintain infection for decades and steroids can precipitate life-threatening hyperinfection',[
 ('Strongyloides always clears within days without treatment','Autoinfection permits prolonged persistence.'),('Only a recent foreign trip can create a risk','Remote exposure can remain clinically important.'),('Normal eosinophils exclude infection and hyperinfection risk','Eosinophilia can be absent, especially in severe or immunosuppressed disease.')],
 'A remote infection can become an immediate immunosuppression hazard', '**Corticosteroids are a major trigger for Strongyloides hyperinfection.**', ['Use risk-based screening and an appropriate treatment strategy before immunosuppression when feasible.','Do not delay emergency treatment of another life-threatening condition without a coordinated plan.'], '**Interpret tests with their limitations.**', ['A single negative stool examination has limited sensitivity.','Serology, repeated or specialized stool testing and clinical risk may all matter.'], [['Remote endemic exposure','Risk can persist'],['Steroids','Hyperinfection trigger'],['Normal eosinophils','Does not rule out']], [ST,ref('CDC Clinical Overview of Strongyloides','https://www.cdc.gov/strongyloides/hcp/clinical-overview/index.html')], 'clinical_scenario')
q('What is the preferred drug for uncomplicated intestinal strongyloidiasis in most suitable patients?', 'Ivermectin',[
 ('Praziquantel','This is not the standard first-line Strongyloides drug.'),('Oral vancomycin','This treats a different organism and disease.'),('Metronidazole','This is not the preferred antihelminthic for Strongyloides.')],
 'Choose the antihelminthic for the actual parasite', '**Ivermectin is first-line therapy for most uncomplicated Strongyloides infection.**', ['Pregnancy, body weight and possible Loa loa coinfection can affect the risk assessment.','Follow-up depends on symptoms, baseline stool positivity and immune status.'], '**Distinguish uncomplicated disease from hyperinfection.**', ['Hyperinfection requires a longer daily treatment approach and immune-suppression review.','Treatment is not complete merely because eosinophils transiently normalize.'], [['Uncomplicated Strongyloides','Ivermectin preferred'],['Loa loa risk','Assess before treatment'],['Hyperinfection','Different intensity and duration']], [ST])
q('A steroid-treated patient has gastrointestinal and pulmonary deterioration with Strongyloides larvae in sputum and enteric Gram-negative bacteremia. What is the best interpretation?', 'Strongyloides hyperinfection with bacterial translocation, requiring urgent daily ivermectin and reduction of immunosuppression when feasible',[
 ('An incidental larva that cannot relate to sepsis','Hyperinfection can carry enteric organisms across the mucosa.'),('A reason to increase corticosteroids as the sole antiparasitic treatment','Steroids can worsen the underlying process.'),('A condition treated adequately by one routine antibacterial dose alone','Antibacterial treatment does not eradicate Strongyloides.')],
 'Escalated larval migration can produce a multisystem emergency', '**Pulmonary involvement and enteric bacteremia are important warning features.**', ['Treat bacterial sepsis alongside the parasite.','Ivermectin is continued until stool and/or sputum studies remain negative for an appropriate interval, commonly two weeks.'], '**Address delivery and immune status.**', ['Ileus or malabsorption may complicate oral therapy and require expert alternatives.','Reduce or stop immunosuppression when clinically possible.'], [['Hyperinfection','High larval burden along usual migration route'],['Enteric bacteremia','Bacterial translocation complication'],['Treatment','Daily antiparasitic therapy plus sepsis care']], [ST], 'clinical_scenario')
q('Which test is generally most useful early for suspected enteric fever before antibiotics are started?', 'Blood culture with susceptibility testing',[
 ('A single Widal titer as definitive confirmation','Serological performance and background titers limit its diagnostic reliability.'),('CA 19-9','This is not an enteric fever diagnostic test.'),('Fecal calprotectin as species confirmation','It cannot identify Salmonella Typhi or Paratyphi.')],
 'Seek microbiological confirmation of a systemic infection', '**Enteric fever is a bacteremic illness, so blood cultures are important.**', ['Sensitivity is imperfect and is affected by prior antibiotics and sample volume.','More than one culture may be needed when suspicion remains high.'], '**Use travel and resistance history to choose initial treatment.**', ['Drug-resistant and extensively resistant strains affect empiric choices.','A negative culture does not automatically exclude the disease in a pretreated patient.'], [['Blood culture','Early systemic diagnostic tool'],['Susceptibility','Directs antibiotic choice'],['Single Widal result','Not definitive']], [ref('CDC Yellow Book: Typhoid and Paratyphoid Fever','https://www.cdc.gov/yellow-book/hcp/travel-associated-infections-diseases/typhoid-and-paratyphoid-fever.html')])
q('A patient with ileocecal inflammation is being evaluated for intestinal tuberculosis versus Crohn disease. Which finding most strongly favors tuberculosis?', 'Caseating granulomas or microbiological confirmation of Mycobacterium tuberculosis in appropriate tissue',[
 ('Any noncaseating granuloma as absolute proof of Crohn disease','Noncaseating granulomas are not exclusive to Crohn disease.'),('A positive interferon-gamma release assay alone as proof of active intestinal disease','It supports infection exposure but does not localize or prove active intestinal TB.'),('Response to a brief steroid course as definitive exclusion of TB','Steroids can suppress symptoms while worsening an infection.')],
 'Evidence of the organism or characteristic tissue necrosis carries more weight than nonspecific inflammation', '**Both diseases can affect the ileocecal region and share imaging or endoscopic findings.**', ['Obtain adequate biopsies for histology and appropriate mycobacterial studies.','A negative test does not exclude TB because tissue yield can be limited.'], '**Avoid uncritical immunosuppression when TB remains plausible.**', ['Integrate exposure, systemic findings, imaging and microbiology.','A diagnostic treatment trial, when necessary, should be specialist-led with predefined reassessment.'], [['Caseation/organism','Strong TB support'],['IGRA alone','Not proof of active bowel TB'],['Noncaseating granuloma','Not disease-specific']], [ref('World Gastroenterology Organisation: Digestive Tract Tuberculosis','https://www.worldgastroenterology.org/guidelines/digestive-tract-tuberculosis/digestive-tract-tuberculosis-english')], 'clinical_scenario')
q('Bloody diarrhea initially improves after an infectious episode, but months of abdominal pain and variable stools continue with a negative appropriate work-up. What is a plausible explanation?', 'Postinfectious irritable bowel syndrome',[
 ('All persistent symptoms necessarily prove viable organisms remain','Symptoms can persist after eradication through altered gut–brain and intestinal function.'),('Repeated antibiotics are mandatory despite no evidence of infection','This can cause harm and is not a diagnostic substitute.'),('IBS is impossible after a documented infection','Infection is a recognized precipitating event in a subset.')],
 'Persistence of symptoms is not synonymous with persistence of the pathogen', '**Postinfectious IBS can follow bacterial or protozoal gastroenteritis.**', ['Exclude relevant ongoing infection and alarm features proportionately.','Temporary carbohydrate malabsorption can be another postinfectious mechanism.'], '**Treat the current syndrome once the assessment supports it.**', ['Explain why repeat blind antimicrobial courses are unlikely to help.','New bleeding, weight loss or inflammatory findings require reassessment.'], [['Persistent pathogen','Requires evidence and targeted therapy'],['Postinfectious IBS','Disorder of gut–brain interaction'],['New alarm feature','Reopen evaluation']], [TR], 'clinical_scenario')
q('A hospital ward has an abrupt outbreak of vomiting and watery diarrhea with a short incubation and rapid person-to-person spread. Which organism is a leading consideration?', 'Norovirus',[
 ('Giardia as the most typical cause of explosive short-incubation vomiting outbreaks','Giardia more often causes a longer-incubation prolonged diarrheal illness.'),('Strongyloides as the usual acute ward outbreak pathogen','Its transmission and clinical pattern differ.'),('Entamoeba histolytica as the typical cause of a brief vomiting-predominant outbreak','This is not its characteristic epidemiology.')],
 'Use outbreak tempo and transmission pattern', '**Norovirus is highly contagious and commonly causes institutional gastroenteritis outbreaks.**', ['Hydration is the main individual treatment.','Contact precautions, environmental cleaning and exclusion of symptomatic food handlers help control spread.'], '**Do not prescribe antibiotics for a viral outbreak by default.**', ['Obtain outbreak testing through the appropriate infection-control pathway.','Vulnerable patients may have more severe dehydration or prolonged illness.'], [['Short outbreak with vomiting','Norovirus concern'],['Treatment','Supportive hydration'],['Control','Infection prevention measures']], [ID], 'clinical_scenario')
q('An immunocompromised patient has persistent diarrhea and an apparently negative routine bacterial stool culture. What is the best next diagnostic principle?', 'Broaden testing to relevant parasites, viruses and opportunistic causes according to immune defect and exposure',[
 ('A negative routine culture excludes all infectious causes','Routine bacterial culture does not cover the full pathogen spectrum.'),('Treat every case as IBS immediately','The immune context materially changes pretest probability.'),('Assume one multiplex panel includes every opportunistic organism','Panel contents and sensitivity vary and must be checked.')],
 'The host defines the missing differential', '**A test only excludes the organisms and syndromes it can actually assess.**', ['Consider coccidian parasites and relevant viral disease in the appropriate host.','Endoscopic tissue may be needed for suspected CMV or another mucosal process.'], '**Combine pathogen evaluation with medication and inflammatory review.**', ['Immunosuppressants themselves can cause diarrhea.','A positive molecular result must still be interpreted for causation rather than carriage.'], [['Routine bacterial culture','Limited organism range'],['Immune defect','Expands differential'],['Tissue-invasive disease','May need endoscopic biopsy']], [ID,TR], 'clinical_scenario')
q('Persistent diarrhea follows travel to a tropical region. What is an appropriate general approach to stool parasite assessment?', 'Use targeted antigen/PCR tests and/or serial ova-and-parasite studies, with special stains or assays requested when indicated',[
 ('One routine microscopy specimen excludes every parasite','Intermittent shedding and method limitations reduce sensitivity.'),('A positive result for any harmless protozoan proves it caused the syndrome','Clinical pathogenicity differs by organism.'),('Stop evaluating if the first bacterial culture is negative','Protozoal infection may not be detected by routine bacterial culture.')],
 'Match laboratory methods to the suspected pathogen', '**Persistent travel-associated diarrhea has a higher protozoal yield than many brief acute episodes.**', ['Giardia, Cryptosporidium and Cyclospora may require specific tests.','Check which organisms a local molecular panel actually includes.'], '**If pathogen studies are unrevealing, reassess the wider differential.**', ['Celiac disease, IBD and postinfectious syndromes may be relevant.','Repeated unselected antimicrobial courses can obscure rather than solve the diagnosis.'], [['Targeted antigen/PCR','Specific organism assessment'],['Serial microscopy','Can improve intermittent shedding detection'],['Negative infectious assessment','Consider noninfectious mechanisms']], [TR])

